import json

# Music notation helper
def note_to_midi(note_str):
    """Convert note string like 'C-4' to MIDI note number"""
    notes = {'C': 0, 'D': 2, 'E': 4, 'F': 5, 'G': 7, 'A': 9, 'B': 11}
    octave = int(note_str[2])
    note_name = note_str[0]
    accidental = 0
    if len(note_str) > 1 and note_str[1] == '#':
        accidental = 1
        note_name = note_str[0]

    return notes[note_name] + accidental + (octave + 1) * 12

# Pattern arrangement for a keygen tune structure
# Each pattern is 64 rows = 4 bars at speed 6, 135 BPM

batch = []

# Set pattern lengths
for p in range(8):
    batch.append({
        "name": "pattern_clear",
        "arguments": {"pattern": p}
    })
    batch.append({
        "name": "pattern_set_length",
        "arguments": {"pattern": p, "rows": 64}
    })

# Pattern 0: Intro - kick and hi-hat only
print("Composing Pattern 0 (Intro)")
pattern = 0
# Kick drum on beat 1 and 3 (every 12 rows at speed 6 = 2 beats)
for row in [0, 12, 24, 36, 48, 60]:
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": pattern,
            "row": row,
            "channel": 0,
            "note": 36,  # C-1 (low kick note)
            "instrument": 1,
            "volume": 64
        }
    })

# Hi-hat on 8th notes
for row in range(6, 64, 6):
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": pattern,
            "row": row,
            "channel": 1,
            "note": 50,  # Any note for percussion
            "instrument": 2,
            "volume": 48
        }
    })

# Pattern 1: Build-up - bass enters with simple riff
print("Composing Pattern 1 (Build-up)")
pattern = 1
# Kick pattern intensifies
for row in [0, 6, 12, 18, 24, 30, 36, 42, 48, 54, 60]:
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": pattern,
            "row": row,
            "channel": 0,
            "note": 36,
            "instrument": 1,
            "volume": 64
        }
    })

# Hi-hat continues
for row in range(3, 64, 6):
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": pattern,
            "row": row,
            "channel": 1,
            "note": 50,
            "instrument": 2,
            "volume": 48
        }
    })

# Bass riff in C minor: C, Eb, G, C (pattern)
bass_pattern = [36, 39, 43, 36]  # C, Eb, G, C in octave 2
bass_rows = [0, 12, 24, 36, 48]
for i, row in enumerate(bass_rows):
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": pattern,
            "row": row,
            "channel": 2,
            "note": bass_pattern[i % 4],
            "instrument": 3,
            "volume": 60
        }
    })

# Pattern 2: Main verse - bass continues, lead enters with arpeggio
print("Composing Pattern 2 (Verse 1)")
pattern = 2
# Kick drum
for row in [0, 6, 12, 18, 24, 30, 36, 42, 48, 54, 60]:
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": pattern,
            "row": row,
            "channel": 0,
            "note": 36,
            "instrument": 1,
            "volume": 64
        }
    })

# Hi-hat
for row in range(3, 64, 6):
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": pattern,
            "row": row,
            "channel": 1,
            "note": 50,
            "instrument": 2,
            "volume": 48
        }
    })

# Bass riff repeats
for i, row in enumerate(bass_rows):
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": pattern,
            "row": row,
            "channel": 2,
            "note": bass_pattern[i % 4],
            "instrument": 3,
            "volume": 60
        }
    })

# Lead synth arpeggio: C5-Eb5-G5-C6 pattern (4 notes)
lead_pattern = [60, 63, 67, 60]  # C5, Eb5, G5, C6
lead_rows = [4, 16, 28, 40, 52]
for i, row in enumerate(lead_rows):
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": pattern,
            "row": row,
            "channel": 3,
            "note": lead_pattern[i % 4],
            "instrument": 4,
            "volume": 55
        }
    })

# Pattern 3: Chorus - higher energy, lead melody
print("Composing Pattern 3 (Chorus)")
pattern = 3
# Faster kick (on every other row for double-time feel)
for row in range(0, 64, 6):
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {
            "pattern": pattern,
            "row": row,
            "channel": 0,
            "note": 36,
            "instrument": 1,
            "volume": 64
        }
