import json

batch = []

# Song order: Intro -> Build-up -> Verse1 -> Chorus -> Verse2 -> Chorus2 -> Outro -> (back to intro)
order_sequence = [0, 1, 2, 3, 4, 5, 6]

for pos, pattern in enumerate(order_sequence):
    batch.append({
        "name": "order_set",
        "arguments": {
            "position": pos,
            "pattern": pattern
        }
    })

# Set the song length and loop point
batch.append({
    "name": "song_set",
    "arguments": {
        "length": len(order_sequence),
        "loop_start": 0
    }
})

with open('/tmp/order.json', 'w') as f:
    json.dump(batch, f)

print(f"Song order created: {order_sequence}")
print(f"Total patterns: {len(order_sequence)}")
print(f"Loop back to position 0 after position {len(order_sequence)-1}")
EOF
"}

